CREATE TABLE policy_citations (
            citation_id INTEGER PRIMARY KEY AUTOINCREMENT,
            message_id INTEGER NOT NULL,
            policy_id INTEGER NOT NULL,
            article_id INTEGER,
            cited_version INTEGER NOT NULL,
            cited_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (message_id)
                REFERENCES messages(message_id),
            FOREIGN KEY (policy_id)
                REFERENCES policy_documents(policy_id),
            FOREIGN KEY (article_id)
                REFERENCES knowledge_articles(article_id)
        );
CREATE TABLE policy_documents (
            policy_id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            category_id INTEGER NOT NULL,
            version INTEGER NOT NULL,
            content TEXT NOT NULL,
            effective_from TEXT NOT NULL,
            effective_to TEXT, policy_code TEXT,
            FOREIGN KEY (category_id)
                REFERENCES categories(category_id)
        );
CREATE TABLE requesters (
            requester_id INTEGER PRIMARY KEY AUTOINCREMENT,
            name TEXT NOT NULL,
            email TEXT NOT NULL UNIQUE,
            role_id INTEGER NOT NULL,
            FOREIGN KEY (role_id) REFERENCES roles(role_id)
        );
CREATE TABLE resolution_feedback (
            feedback_id INTEGER PRIMARY KEY AUTOINCREMENT,
            ticket_id INTEGER NOT NULL,
            resolution_note TEXT NOT NULL,
            resolved_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (ticket_id)
                REFERENCES tickets(ticket_id)
        );
CREATE TABLE roles (
            role_id INTEGER PRIMARY KEY AUTOINCREMENT,
            role_name TEXT NOT NULL UNIQUE
        );
CREATE TABLE routing_rules (
            rule_id INTEGER PRIMARY KEY AUTOINCREMENT,
            category_id INTEGER NOT NULL,
            team_name TEXT NOT NULL,
            is_authorized INTEGER NOT NULL DEFAULT 1
                CHECK (is_authorized IN (0, 1)),
            UNIQUE(category_id, team_name),
            FOREIGN KEY (category_id)
                REFERENCES categories(category_id)
        );
CREATE TABLE sla (
            sla_id INTEGER PRIMARY KEY AUTOINCREMENT,
            ticket_id INTEGER NOT NULL UNIQUE,
            response_deadline TEXT NOT NULL,
            resolution_deadline TEXT NOT NULL,
            first_response_at TEXT,
            resolved_at TEXT, sla_code TEXT, breached INTEGER NOT NULL DEFAULT 0,
            FOREIGN KEY (ticket_id)
                REFERENCES tickets(ticket_id)
        );
CREATE TABLE sla_business_hours (
            schedule_id INTEGER PRIMARY KEY AUTOINCREMENT,
            weekday INTEGER NOT NULL
                CHECK (weekday BETWEEN 0 AND 6),
            start_time TEXT NOT NULL,
            end_time TEXT NOT NULL,
            is_working_day INTEGER NOT NULL
                CHECK (is_working_day IN (0, 1)),
            UNIQUE(weekday)
        );
CREATE TABLE terms (
            term_id INTEGER PRIMARY KEY AUTOINCREMENT,
            term_name TEXT NOT NULL UNIQUE,
            start_date TEXT NOT NULL,
            end_date TEXT NOT NULL
        );
CREATE TABLE ticket_events (
            event_id INTEGER PRIMARY KEY AUTOINCREMENT,
            ticket_id INTEGER NOT NULL,
            event_type TEXT NOT NULL,
            event_description TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            FOREIGN KEY (ticket_id)
                REFERENCES tickets(ticket_id)
        );
CREATE TABLE tickets (
            ticket_id INTEGER PRIMARY KEY AUTOINCREMENT,
            requester_id INTEGER NOT NULL,
            category_id INTEGER NOT NULL,
            term_id INTEGER,
            subject TEXT NOT NULL,
            description TEXT NOT NULL,
            status TEXT NOT NULL DEFAULT 'Open'
                CHECK (status IN (
                    'Open',
                    'Assigned',
                    'In Progress',
                    'Escalated',
                    'Resolved',
                    'Closed'
                )),
            created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
            updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, ticket_number TEXT, priority TEXT NOT NULL DEFAULT 'Normal',
            FOREIGN KEY (requester_id)
                REFERENCES requesters(requester_id),
            FOREIGN KEY (category_id)
                REFERENCES categories(category_id),
            FOREIGN KEY (term_id)
                REFERENCES terms(term_id)
        );
CREATE INDEX idx_tickets_status
            ON tickets(status);
CREATE INDEX idx_tickets_category
            ON tickets(category_id);
CREATE INDEX idx_messages_ticket
            ON messages(ticket_id);
CREATE INDEX idx_events_ticket
            ON ticket_events(ticket_id);
CREATE INDEX idx_citations_message
            ON policy_citations(message_id);
CREATE UNIQUE INDEX idx_tickets_ticket_number
            ON tickets(ticket_number)
        ;
CREATE UNIQUE INDEX idx_messages_message_number
            ON messages(message_number)
        ;
CREATE UNIQUE INDEX idx_articles_article_code
            ON knowledge_articles(article_code)
        ;
DELETE FROM "sqlite_sequence";
COMMIT;
